<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><?php $data=$record??$old??[]; ?><div class="card"><div class="form-grid"><div class="form-group"><label>Name <span class="required">*</span></label><input name="name" required value="<?= $e($data['name'] ?? '') ?>"></div><div class="form-group"><label>Slug</label><input name="slug" value="<?= $e($data['slug'] ?? '') ?>"><small class="cr-muted">Leave blank to generate from name.</small></div><div class="form-group full-width"><label>Description</label><textarea name="description" rows="4"><?= $e($data['description'] ?? '') ?></textarea></div><div class="form-group"><label>Status</label><select name="status"><option value="Active" <?= ($data['status']??'Active')==='Active'?'selected':'' ?>>Active</option><option value="Inactive" <?= ($data['status']??'')==='Inactive'?'selected':'' ?>>Inactive</option></select></div></div></div>
